mapper.select:
select t.evasion_id evasionId,t.car_num carNum,t.community_id communityId,
t.pa_id paId,t.pa_num paNum,t.box_id boxId,t.inout_id inoutId,t.ci_id ciId,
t.in_time inTime,t.evasion_time evasionTime,t.amount amount,t.state state,
t.remark remark,t.status_cd statusCd,t.create_time createTime,
t.photo_jpg photoJpg
from car_inout_evasion t
where 1=1
and t.status_cd = '0'

    and t.evasion_id= #{evasionId}


    and t.car_num like concat('%', #{carNum}, '%')


    and t.community_id= #{communityId}


    and t.evasion_time >= #{evasionTimeStart}


    and t.evasion_time <= #{evasionTimeEnd}


    and t.state = #{state}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update car_inout_evasion t set t.status_cd = #{statusCd}

    , t.state= #{state}


    , t.remark= #{remark}

where 1=1

    and t.evasion_id= #{evasionId}

mapper.select:
select count(1) count
from car_inout_evasion t
where 1=1
and t.status_cd = '0'

    and t.car_num like concat('%', #{carNum}, '%')


    and t.community_id= #{communityId}


    and t.evasion_time >= #{evasionTimeStart}


    and t.evasion_time <= #{evasionTimeEnd}


    and t.state = #{state}
